            background: rgba(0, 212, 255, 0.12);
            color: var(--accent-cyan);
            border: 1px solid rgba(0, 212, 255, 0.3);
        }
        .chip-magenta {
            background: rgba(255, 0, 110, 0.12);
            color: var(--accent-magenta);
            border: 1px solid rgba(255, 0, 110, 0.3);
        }
        .chip-amber {
            background: rgba(255, 179, 0, 0.12);
            color: var(--accent-amber);
            border: 1px solid rgba(255, 179, 0, 0.3);
        }
        .chip-green {
            background: rgba(0, 255, 157, 0.12);
            color: var(--accent-green);
            border: 1px solid rgba(0, 255, 157, 0.3);
        }

        /* Card container */
        .glass-card {
            background: var(--bg-card);
            border: 1px solid var(--bg-card-border);
            border-radius: 8px;
            padding: clamp(0.8rem, 1.5vw, 1.5rem);
            backdrop-filter: blur(8px);
        }

        /* Horizontal divider */
        .divider {
            width: 100%;
            height: 1px;
            background: linear-gradient(90deg, var(--accent-cyan), transparent);
            opacity: 0.3;
            margin: clamp(0.4rem, 0.8vh, 0.8rem) 0;
        }

        /* ===========================================
           SLIDE 1 — TITLE SLIDE
           =========================================== */
        .title-slide {
            background:
                radial-gradient(ellipse at 15% 85%, rgba(0, 212, 255, 0.12) 0%, transparent 55%),
                radial-gradient(ellipse at 85% 15%, rgba(255, 0, 110, 0.1) 0%, transparent 50%),
                radial-gradient(ellipse at 50% 50%, rgba(9, 20, 40, 0.9) 0%, transparent 80%),
                var(--bg-primary);
            justify-content: flex-end;
            padding-bottom: clamp(3rem, 7vh, 6rem);
        }

        .title-slide .slide-content {
            justify-content: flex-end;
            padding-bottom: 0;
        }

        .title-slide .hero-label {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent-cyan);
            letter-spacing: 0.2em;
            text-transform: uppercase;
            margin-bottom: clamp(0.5rem, 1.2vh, 1rem);
            opacity: 0.85;
        }

        .title-slide h1 {
            font-family: var(--font-display);
            font-size: clamp(1.8rem, 4.2vw, 3.6rem);
            font-weight: 700;
            line-height: 1.08;
            letter-spacing: -0.03em;
            color: var(--text-primary);
            max-width: 16ch;
            margin-bottom: clamp(0.8rem, 1.8vh, 1.6rem);
        }

        .title-slide h1 .accent-word {
            color: var(--accent-cyan);
            display: block;
        }

        .title-slide .tagline {
            font-family: var(--font-body);
            font-size: clamp(0.8rem, 1.4vw, 1.05rem);
            color: var(--text-secondary);
            max-width: 55ch;
            line-height: 1.55;
            margin-bottom: clamp(1rem, 2vh, 1.8rem);
        }

        .title-slide .meta-row {
            display: flex;
            align-items: center;
            gap: clamp(0.8rem, 1.5vw, 1.5rem);
            flex-wrap: wrap;
        }

        .title-slide .arxiv-link {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
            letter-spacing: 0.05em;
            text-decoration: none;
            border-bottom: 1px solid transparent;
            transition: color 0.2s, border-color 0.2s;
        }

        /* Animated scan line on title slide */
        .scan-line {
            position: absolute;
            left: 0;
            width: 100%;
            height: 1px;
            background: linear-gradient(90deg, transparent, var(--accent-cyan), transparent);
            opacity: 0.4;
            animation: scanDown 8s linear infinite;
        }

        @keyframes scanDown {
            0%   { top: 0%; opacity: 0; }
            5%   { opacity: 0.4; }
            95%  { opacity: 0.4; }
            100% { top: 100%; opacity: 0; }
        }

        /* Pulsing corner accent */
        .corner-accent {
            position: absolute;
            top: clamp(1rem, 3vh, 2.5rem);
            right: clamp(1.5rem, 4vw, 3.5rem);
            width: clamp(60px, 8vw, 110px);
            height: clamp(60px, 8vw, 110px);
            border: 1px solid rgba(0, 212, 255, 0.2);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .corner-accent::after {
            content: '';
            width: 60%;
            height: 60%;
            border-radius: 50%;
            background: radial-gradient(circle, rgba(0, 212, 255, 0.3), transparent);
            animation: pulse 3s ease-in-out infinite;
        }
        @keyframes pulse {
            0%, 100% { transform: scale(1); opacity: 0.7; }
            50% { transform: scale(1.25); opacity: 1; }
        }

        /* ===========================================
           SLIDE 2 — SUBSTITUTION THREAT
           =========================================== */
        .threat-slide {
            background:
                radial-gradient(ellipse at 80% 20%, rgba(255, 0, 110, 0.1) 0%, transparent 50%),
                var(--bg-primary);
        }

        .threat-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.8rem, 1.5vw, 1.5rem);
            margin-top: clamp(0.6rem, 1.2vh, 1.2rem);
        }

        .threat-item {
            background: rgba(10, 22, 45, 0.7);
            border: 1px solid rgba(0, 212, 255, 0.1);
            border-radius: 6px;
            padding: clamp(0.6rem, 1.2vw, 1.1rem);
            display: flex;
            gap: clamp(0.5rem, 1vw, 0.9rem);
            align-items: flex-start;
            transition: border-color 0.3s;
        }
        .threat-item:hover { border-color: rgba(0, 212, 255, 0.3); }

        .threat-number {
            font-family: var(--font-mono);
            font-size: clamp(1.2rem, 2.5vw, 2rem);
            font-weight: 600;
            color: rgba(0, 212, 255, 0.25);
            line-height: 1;
            min-width: 1.5ch;
        }

        .threat-label {
            font-family: var(--font-display);
            font-size: clamp(0.75rem, 1.3vw, 1rem);
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 0.2em;
        }

        .threat-desc {
            font-size: clamp(0.62rem, 1vw, 0.8rem);
            color: var(--text-secondary);
            line-height: 1.45;
        }

        .hypothesis-box {
            margin-top: clamp(0.6rem, 1.2vh, 1.2rem);
            padding: clamp(0.6rem, 1.2vw, 1rem);
            border-left: 2px solid var(--accent-cyan);
            background: rgba(0, 212, 255, 0.04);
            border-radius: 0 6px 6px 0;
        }

        .hypothesis-text {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--text-secondary);
            line-height: 1.6;
        }

        .hypothesis-text strong {
            color: var(--accent-cyan);
            font-weight: 600;
        }

        /* ===========================================
           SLIDE 3 — BENCHMARK TABLE
           =========================================== */
        .benchmark-slide {
            background:
                radial-gradient(ellipse at 20% 80%, rgba(0, 212, 255, 0.08) 0%, transparent 50%),
                var(--bg-primary);
        }

        .bench-table-wrap {
            overflow: hidden;
            border-radius: 6px;
            border: 1px solid rgba(0, 212, 255, 0.15);
            margin-top: clamp(0.5rem, 1vh, 1rem);
        }

        .bench-table {
            width: 100%;
            border-collapse: collapse;
            font-family: var(--font-mono);
            font-size: clamp(0.55rem, 0.9vw, 0.78rem);
        }

        .bench-table thead {
            background: rgba(0, 212, 255, 0.08);
        }

        .bench-table th {
            padding: clamp(0.35rem, 0.7vh, 0.6rem) clamp(0.4rem, 0.8vw, 0.8rem);
            text-align: left;
            color: var(--accent-cyan);
            font-weight: 600;
            letter-spacing: 0.06em;
            font-size: clamp(0.52rem, 0.8vw, 0.72rem);
            border-bottom: 1px solid rgba(0, 212, 255, 0.2);
            white-space: nowrap;
        }

        .bench-table td {
            padding: clamp(0.28rem, 0.55vh, 0.5rem) clamp(0.4rem, 0.8vw, 0.8rem);
            color: var(--text-secondary);
            border-bottom: 1px solid rgba(255, 255, 255, 0.04);
            white-space: nowrap;
            font-size: clamp(0.52rem, 0.82vw, 0.74rem);
        }

        .bench-table .model-name {
            color: var(--text-primary);
            font-weight: 500;
        }

        .bench-table .fp8-row td {
            background: rgba(255, 0, 110, 0.04);
            color: rgba(180, 160, 170, 0.9);
        }

        .bench-table .fp8-row .model-name {
            color: rgba(255, 140, 170, 0.85);
        }

        /* Within-error-bar value highlight */
        .within-err {
            color: var(--accent-amber);
        }

        .bench-note {
            margin-top: clamp(0.4rem, 0.8vh, 0.7rem);
            font-size: clamp(0.58rem, 0.9vw, 0.76rem);
            color: var(--text-muted);
            display: flex;
            align-items: center;
            gap: 0.5em;
        }
        .bench-note::before {
            content: '▶';
            color: var(--accent-amber);
            font-size: 0.7em;
        }

        /* ===========================================
           SLIDE 4 — TEMPERATURE SCALING
           =========================================== */
        .temp-slide {
            background:
                radial-gradient(ellipse at 70% 30%, rgba(255, 179, 0, 0.08) 0%, transparent 50%),
                var(--bg-primary);
        }

        .temp-layout {
            display: grid;
            grid-template-columns: 1fr 1.6fr;
            gap: clamp(1rem, 2vw, 2rem);
            align-items: center;
            margin-top: clamp(0.5rem, 1vh, 1rem);
        }

        .temp-points {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 0.8vh, 0.8rem);
        }

        .temp-point {
            display: flex;
            gap: 0.7em;
            align-items: flex-start;
        }

        .temp-icon {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent-amber);
            font-weight: 600;
            padding-top: 0.1em;
            min-width: 2ch;
        }

        .temp-point-text {
            font-size: clamp(0.68rem, 1.1vw, 0.9rem);
            color: var(--text-secondary);
            line-height: 1.45;
        }

        .temp-point-text strong {
            color: var(--text-primary);
            font-weight: 600;
        }

        .temp-fig {
            border-radius: 6px;
            border: 1px solid rgba(255, 179, 0, 0.15);
            overflow: hidden;
            background: rgba(10, 22, 40, 0.5);
        }

        .temp-fig img {
            width: 100%;
            max-height: min(52vh, 380px);
            object-fit: contain;
            display: block;
        }

        .temp-fig-caption {
            padding: 0.4rem 0.7rem;
            font-family: var(--font-mono);
            font-size: clamp(0.52rem, 0.8vw, 0.68rem);
            color: var(--text-muted);
            border-top: 1px solid rgba(255, 179, 0, 0.1);
        }

        /* ===========================================
           SLIDE 5 — LOG PROB NONDETERMINISM
           =========================================== */
        .logprob-slide {
            background:
                radial-gradient(ellipse at 30% 70%, rgba(255, 0, 110, 0.1) 0%, transparent 50%),
                var(--bg-primary);
        }

        .logprob-layout {
            display: grid;
            grid-template-columns: 1.5fr 1fr;
            gap: clamp(1rem, 2vw, 2rem);
            align-items: center;
            margin-top: clamp(0.5rem, 1vh, 1rem);
        }

        .logprob-fig {
            border-radius: 6px;
            border: 1px solid rgba(255, 0, 110, 0.15);
            overflow: hidden;
            background: rgba(10, 22, 40, 0.5);
        }

        .logprob-fig img {
            width: 100%;
            max-height: min(52vh, 370px);
            object-fit: contain;
            display: block;
        }

        .logprob-fig-caption {
            padding: 0.4rem 0.7rem;
            font-family: var(--font-mono);
            font-size: clamp(0.52rem, 0.8vw, 0.68rem);
            color: var(--text-muted);
            border-top: 1px solid rgba(255, 0, 110, 0.1);
        }

        .logprob-points {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1vh, 1rem);
        }

        .logprob-point {
            padding: clamp(0.5rem, 1vw, 0.9rem);
            border-radius: 6px;
            border: 1px solid rgba(255, 0, 110, 0.1);
            background: rgba(255, 0, 110, 0.04);
        }

        .logprob-point-label {
            font-family: var(--font-mono);
            font-size: clamp(0.58rem, 0.9vw, 0.74rem);
            color: var(--accent-magenta);
            font-weight: 600;
            margin-bottom: 0.3em;
            letter-spacing: 0.05em;
        }

        .logprob-point-text {
            font-size: clamp(0.62rem, 1vw, 0.82rem);
            color: var(--text-secondary);
            line-height: 1.45;
        }

        /* ===========================================
           SLIDE 6 — RANDOMIZED SUBSTITUTION
           =========================================== */
        .random-slide {
            background:
                radial-gradient(ellipse at 60% 40%, rgba(255, 179, 0, 0.07) 0%, transparent 50%),
                var(--bg-primary);
        }

        .attack-diagram {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: clamp(0.6rem, 1.2vw, 1.2rem);
            margin-top: clamp(0.5rem, 1vh, 1rem);
        }

        .attack-node {
            text-align: center;
            padding: clamp(0.6rem, 1.2vw, 1.2rem);
            border-radius: 8px;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.4em;
        }

        .attack-node.api-node {
            border: 1px solid rgba(0, 212, 255, 0.25);
            background: rgba(0, 212, 255, 0.06);
        }
        .attack-node.real-node {
            border: 1px solid rgba(0, 255, 157, 0.25);
            background: rgba(0, 255, 157, 0.06);
        }
        .attack-node.fake-node {
            border: 1px solid rgba(255, 0, 110, 0.25);
            background: rgba(255, 0, 110, 0.06);
        }

        .attack-node-icon {
            font-family: var(--font-mono);
            font-size: clamp(1.2rem, 2.5vw, 2rem);
            line-height: 1;
        }

        .attack-node-title {
            font-family: var(--font-display);
            font-size: clamp(0.7rem, 1.1vw, 0.9rem);
            font-weight: 600;
            color: var(--text-primary);
        }

        .attack-node-desc {
            font-size: clamp(0.58rem, 0.9vw, 0.76rem);
            color: var(--text-secondary);
            text-align: center;
            line-height: 1.4;
        }

        .formula-block {
            margin-top: clamp(0.6rem, 1.2vh, 1.2rem);
            padding: clamp(0.6rem, 1.2vw, 1.1rem);
            border-left: 2px solid var(--accent-amber);
            background: rgba(255, 179, 0, 0.04);
            border-radius: 0 6px 6px 0;
        }

        .formula-text {
            font-family: var(--font-mono);
            font-size: clamp(0.65rem, 1.1vw, 0.88rem);
            color: var(--text-secondary);
            line-height: 1.7;
        }

        .formula-text .formula-var {
            color: var(--accent-amber);
            font-weight: 600;
        }

        .formula-text .formula-key {
            color: var(--accent-cyan);
        }

        .consequence-row {
            margin-top: clamp(0.4rem, 0.8vh, 0.8rem);
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1vw, 1rem);
            flex-wrap: wrap;
        }

        /* ===========================================
           SLIDE 7 — SOFTWARE METHODS SUMMARY
           =========================================== */
        .summary-slide {
            background:
                radial-gradient(ellipse at 90% 50%, rgba(255, 0, 110, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 10% 50%, rgba(0, 212, 255, 0.06) 0%, transparent 50%),
                var(--bg-primary);
        }

        .matrix-table-wrap {
            overflow: hidden;
            border-radius: 6px;
            border: 1px solid rgba(255, 0, 110, 0.2);
            margin-top: clamp(0.5rem, 1vh, 1rem);
        }

        .matrix-table {
            width: 100%;
            border-collapse: collapse;
            font-size: clamp(0.6rem, 1vw, 0.84rem);
        }

        .matrix-table thead {
            background: rgba(255, 0, 110, 0.1);
        }

        .matrix-table th {
            padding: clamp(0.4rem, 0.8vh, 0.7rem) clamp(0.5rem, 1vw, 1rem);
            text-align: left;
            color: var(--accent-magenta);
            font-family: var(--font-mono);
            font-weight: 600;
            letter-spacing: 0.06em;
            font-size: clamp(0.55rem, 0.85vw, 0.72rem);
            border-bottom: 1px solid rgba(255, 0, 110, 0.25);
        }

        .matrix-table td {
            padding: clamp(0.45rem, 0.9vh, 0.75rem) clamp(0.5rem, 1vw, 1rem);
            border-bottom: 1px solid rgba(255, 255, 255, 0.05);
            vertical-align: top;
            line-height: 1.45;
            color: var(--text-secondary);
        }

        .matrix-table tbody tr:last-child td {
            border-bottom: none;
        }

        .matrix-table tbody tr:hover td {
            background: rgba(255, 0, 110, 0.04);
        }

        .method-label {
            font-family: var(--font-display);
            font-weight: 600;
            font-size: clamp(0.65rem, 1.05vw, 0.88rem);
            color: var(--text-primary);
            white-space: nowrap;
        }

        .fail-tag {
            display: inline-block;
            padding: 0.15em 0.55em;
            border-radius: 3px;
            font-family: var(--font-mono);
            font-size: clamp(0.5rem, 0.78vw, 0.65rem);
            font-weight: 600;
            letter-spacing: 0.04em;
            margin-bottom: 0.3em;
        }
        .fail-tag.critical {
            background: rgba(255, 0, 110, 0.15);
            color: var(--accent-magenta);
            border: 1px solid rgba(255, 0, 110, 0.3);
        }
        .fail-tag.high {
            background: rgba(255, 179, 0, 0.15);
            color: var(--accent-amber);
            border: 1px solid rgba(255, 179, 0, 0.3);
        }

        .verdict-box {
            margin-top: clamp(0.5rem, 1vh, 1rem);
            padding: clamp(0.5rem, 1vw, 0.9rem);
            border: 1px solid rgba(255, 0, 110, 0.25);
            border-radius: 6px;
            background: rgba(255, 0, 110, 0.05);
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1vw, 1rem);
        }

        .verdict-icon {
            font-family: var(--font-mono);
            font-size: clamp(1rem, 2vw, 1.5rem);
            color: var(--accent-magenta);
            min-width: 1.5ch;
        }

        .verdict-text {
            font-size: clamp(0.65rem, 1.1vw, 0.9rem);
            color: var(--text-primary);
            line-height: 1.45;
        }

        /* ===========================================
           SLIDE 8 — TEE SOLUTION
           =========================================== */
        .tee-slide {
            background:
                radial-gradient(ellipse at 20% 20%, rgba(0, 255, 157, 0.1) 0%, transparent 55%),
                radial-gradient(ellipse at 80% 80%, rgba(0, 212, 255, 0.07) 0%, transparent 50%),
                var(--bg-primary);
        }

        .tee-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.8rem, 1.6vw, 1.6rem);
            margin-top: clamp(0.5rem, 1vh, 1rem);
        }

        .tee-props {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 0.8vh, 0.8rem);
        }

        .tee-prop {
            display: flex;
            gap: 0.7em;
            align-items: flex-start;
            padding: clamp(0.5rem, 1vw, 0.9rem);
            border-radius: 6px;
            border: 1px solid rgba(0, 255, 157, 0.12);
            background: rgba(0, 255, 157, 0.04);
            transition: border-color 0.3s;
        }
        .tee-prop:hover { border-color: rgba(0, 255, 157, 0.3); }

        .tee-prop-icon {
            font-size: clamp(1rem, 1.8vw, 1.4rem);
            min-width: 1.4ch;
        }

        .tee-prop-label {
            font-family: var(--font-display);
            font-size: clamp(0.7rem, 1.2vw, 0.95rem);
            font-weight: 600;
            color: var(--accent-green);
            margin-bottom: 0.2em;
        }

        .tee-prop-desc {
            font-size: clamp(0.6rem, 0.95vw, 0.8rem);
            color: var(--text-secondary);
            line-height: 1.45;
        }

        .contrast-panel {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 0.8vh, 0.8rem);
        }

        .contrast-header {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            letter-spacing: 0.1em;
            text-transform: uppercase;
            margin-bottom: 0.2em;
        }

        .contrast-header.fail { color: var(--accent-magenta); }
        .contrast-header.pass { color: var(--accent-green); }

        .contrast-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.6vh, 0.55rem);
        }

        .contrast-list li {
            font-size: clamp(0.62rem, 1vw, 0.83rem);
            color: var(--text-secondary);
            display: flex;
            gap: 0.5em;
            line-height: 1.4;
        }

        .contrast-list li::before {
            font-family: var(--font-mono);
            font-weight: 700;
            min-width: 1.2ch;
            padding-top: 0.05em;
        }

        .contrast-list.fail li::before {
            content: '✗';
            color: var(--accent-magenta);
        }

        .contrast-list.pass li::before {
            content: '✓';
            color: var(--accent-green);
        }

        .nvidia-badge {
            margin-top: clamp(0.4rem, 0.8vh, 0.8rem);
            padding: clamp(0.4rem, 0.8vw, 0.7rem);
            border-radius: 5px;
            border: 1px solid rgba(0, 255, 157, 0.2);
            background: rgba(0, 255, 157, 0.06);
            font-family: var(--font-mono);
            font-size: clamp(0.58rem, 0.9vw, 0.76rem);
            color: var(--accent-green);
        }

        /* ===========================================
           SLIDE 9 — KEY TAKEAWAYS
           =========================================== */
        .takeaway-slide {
            background:
                radial-gradient(ellipse at 50% 0%, rgba(0, 212, 255, 0.1) 0%, transparent 50%),
                radial-gradient(ellipse at 50% 100%, rgba(0, 255, 157, 0.07) 0%, transparent 50%),
                var(--bg-primary);
        }

        .takeaway-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: clamp(0.5rem, 1vw, 1rem);
            margin-top: clamp(0.5rem, 1vh, 1rem);
        }

