        <div class="eyebrow reveal stagger-1" style="--accent-cyan: #00ff9d; color: var(--accent-green);">
            <span style="width: clamp(16px, 2vw, 28px); height: 1px; background: var(--accent-green); box-shadow: 0 0 6px rgba(0,255,157,0.3); display: inline-block; margin-right: 0.5em;"></span>
