        </div>

        <h2 class="slide-title reveal stagger-2" style="margin: clamp(0.3rem, 0.6vh, 0.6rem) 0 clamp(0.3rem, 0.6vh, 0.6rem);">
            Trusted Execution Environments:<br>
            <span class="hl-green">Provable Cryptographic Model Integrity</span>
        </h2>

        <div class="tee-layout reveal stagger-3">
            <div class="tee-props">
                <div class="tee-prop">
                    <div class="tee-prop-icon">🔒</div>
                    <div>
                        <div class="tee-prop-label">Hardware Attestation</div>
                        <div class="tee-prop-desc">Cryptographic proof that specific model weights are loaded and the correct inference code is executing — not just claimed.</div>
                    </div>
                </div>
                <div class="tee-prop">
                    <div class="tee-prop-icon">⚡</div>
                    <div>
                        <div class="tee-prop-label">Modest Overhead</div>
